begin;
update sessions set starts_on='2026-10-13', description='Six weeks of total-body conditioning, nutrition habits, check-ins, and accountability. Tuesday 6 AM, Wednesday 7 PM, Saturday 7:30 or 9 AM. November 7 classes are on Zoom.' where id='e513111f-17b2-4f2d-bc4d-18593c448378';
update class_meetings set drop_in_enabled=false where drop_in_enabled=true and starts_at>now();
update consultation_slots set active=false where id='068af6eb-0663-4f1c-86d4-922bb54322f2' and not exists(select 1 from consultation_bookings b where b.slot_id=consultation_slots.id and b.status='booked');
-- Reserve an hour; keep the original 9:30, 10:30, etc. daytime starts, and preserve all booked slots.
update consultation_slots s set active=false where active and starts_at>now() and extract(minute from starts_at at time zone 'America/Detroit')=0 and not exists(select 1 from consultation_bookings b where b.slot_id=s.id and b.status='booked');
update consultation_slots s set duration_minutes=60 where active and starts_at>now() and not exists(select 1 from consultation_bookings b where b.slot_id=s.id and b.status='booked');
update consultation_slots s set active=false where active and starts_at>now() and not exists(select 1 from consultation_bookings own where own.slot_id=s.id and own.status='booked') and exists(select 1 from consultation_bookings b join consultation_slots booked on b.slot_id=booked.id where b.status='booked' and booked.starts_at < s.starts_at + make_interval(mins=>s.duration_minutes) and booked.starts_at+make_interval(mins=>booked.duration_minutes)>s.starts_at);
update site_content set value=replace(value::text,'October 14','October 13')::jsonb where content_key like 'website:%' and value::text like '%October 14%';
update website_content set hero_eyebrow=replace(hero_eyebrow,'October 14','October 13'), offer_eyebrow=replace(offer_eyebrow,'October 14','October 13'), final_body=replace(final_body,'October 14','October 13') where page_key='homepage';
update site_content set value=value || '{"join_label":"Join group classes"}'::jsonb where content_key='website:header';
update site_content set value=value || '{"final_body":"Join the six-week session. If it has already started, ask Kelsey about space and a prorated price.","secondary_cta_label":"Ask about joining late","secondary_cta_url":"contact.html","schedule_body":"Switch Saturday times or make up a class within the same session. Just communicate your plans with Kelsey. November 7 classes are on Zoom while Kelsey is out of town."}'::jsonb where content_key='website:coaching';
update site_content set value=jsonb_set(value,'{visual_overrides}',to_jsonb((select coalesce(jsonb_agg(x),'[]'::jsonb)::text from jsonb_array_elements((value->>'visual_overrides')::jsonb) x where x->>'selector' not like '%aside > p:nth-of-type(2)%'))) where content_key='website:coaching';
update site_content set value=value || '{"hero_cta_label":"Book a free consultation","hero_cta_url":"book.html","final_cta_label":"Book a free consultation","final_cta_url":"book.html","final_body":"Start with a free consultation. Kelsey will help you understand the plan and arrange payment when you are ready."}'::jsonb where content_key='website:training';
update site_content set value=value || '{"app_cta_label":"Try the app—no account needed","app_cta_url":"https://portal.holden.health/demo","visual_overrides":"[]","offer_body":"Choose two days each week for $199 or three for $249. Stripe adds $4 for online payment; Venmo, cash, and check have no online fee.","final_body":"The first six-week session runs October 13–November 21 in Plymouth. Choose two days per week for $199 or three for $249. Add $4 only for online Stripe payment.","app_access":"Works in your phone’s browser. Every membership includes full app access. Assigned workouts and coaching support follow your chosen program."}'::jsonb where content_key='website:homepage';
update site_content set value=jsonb_set(value,'{community_body}',to_jsonb(replace(value->>'community_body','Before Holden Health became an online coaching practice','Before Holden Health grew into in-person and online coaching'))) where content_key='website:about';
update site_content set value=jsonb_set(value,'{drop_in_visible}','false'::jsonb) where content_key='website:settings';
commit;
select jsonb_build_object('start',(select starts_on from sessions where id='e513111f-17b2-4f2d-bc4d-18593c448378'),'future_dropins',(select count(*) from class_meetings where drop_in_enabled and starts_at>now()),'late_slot_active',(select active from consultation_slots where id='068af6eb-0663-4f1c-86d4-922bb54322f2'),'future_durations',(select jsonb_agg(distinct duration_minutes) from consultation_slots where active and starts_at>now()),'old_dates',(select count(*) from site_content where content_key like 'website:%' and value::text like '%October 14%'));
